<script module lang="ts">
/**
 * Navigation as text, with an optional Button-styled variant (`design/components/link.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/link.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import { Icon, agentMember, agentPress, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/link.module.css'

export type LinkVariant = NonNullable<LinkProps['variant']>

export interface LinkButtonGrid {
  solid: 'accent'
  soft: 'accent'
  outline: 'accent' | 'neutral'
  ghost: 'accent' | 'neutral'
}

export interface LinkProps {
  buttonVariant?: 'solid' | 'soft' | 'outline' | 'ghost'
  children: Snippet
  /**
   * Adds the glyph, the new tab, and the `rel` that makes it safe.
   */
  external?: boolean
  href: string
  /**
   * The app's router. A click the browser would follow in this tab calls it with `href` in place
   * of the browser's navigation; a click with a modifier key or another button, and a click on
   * an `external` link, stay the browser's. It routes and does nothing else: a click that
   * changes data is a Button.
   */
  onNavigate?: (href: string) => void
  /**
   * Control size, as on Button.
   */
  size?: 'sm' | 'md' | 'lg'
  tone?: 'accent' | 'neutral'
  /**
   * `inline` sits inside a sentence and `standalone` is a row or a title.
   */
  variant?: 'inline' | 'standalone' | 'button'
}
</script>

<script lang="ts">
let {
  buttonVariant = 'soft',
  children,
  external = false,
  href,
  onNavigate,
  size = 'md',
  tone = 'accent',
  variant = 'inline',
}: LinkProps = $props()
const joined = joinSlot(undefined, () => ({ size: size }))
const listening = {
  get navigate() {
    return onNavigate !== undefined
  },
}
let control = $state<HTMLElement | null>(null)
const navigatesHere = $derived(
  (event: MouseEvent): boolean =>
    !event.defaultPrevented &&
    event.button === 0 &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey,
)
const route = $derived((event: MouseEvent): void => {
  if (external || !navigatesHere(event)) return
  event.preventDefault()
  onNavigate?.(href)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Link',
    element: () => control,
    state: () => ({ external: external }),
    actions: {
      press: () =>
        (() => {
          if (external)
            throw new Error('An external link opens a new tab, which only a person’s press opens.')
          agentPress(control)
        })(),
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if variant === 'button'
    }<a
      bind:this={control}
      class={styles.costume}
      {href}
      data-variant={buttonVariant}
      data-tone={tone}
      data-size={size}
      data-external={(external) ? '' : undefined}
      target={(external) ? '_blank' : undefined}
      rel={(external) ? 'noreferrer' : undefined}
      data-member="link"
      onclick={(event) => { if (listening.navigate) route(event) }}
      ><span class={styles.costumeLabel}>{@render children?.()}</span
      >{#if external
        }<span class={styles.costumeGlyph}><Icon name="open-external" {size} /></span
      >{/if
    }</a
  >{:else
    }<a
      bind:this={control}
      class={styles.link}
      {href}
      data-variant={variant}
      data-external={(external) ? '' : undefined}
      target={(external) ? '_blank' : undefined}
      rel={(external) ? 'noreferrer' : undefined}
      data-member="link"
      onclick={(event) => { if (listening.navigate) route(event) }}
      >{@render children?.()
      }{#if external}<Icon name="open-external" size="sm" />{/if
    }</a
  >{/if
}{/if
}{@render joined.end?.()}
